effect.shader:
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0/3.0, 2.0/3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

void main() {
    vec4 texColor = texture2DCv(inputImg.texture, acScreenNorm);
    vec3 color = texColor.rgb;

    // Shadertoy-style grayscale brightness, scaled by parameter
    float lum = dot(color, vec3(0.369, 1.000, 0.000)) * brightness;
    lum = clamp(lum, 0.0, 1.0);

    // Base tint from color picker, apply hue shift in degrees
    vec3 tint = tintColor.rgb;
    vec3 tintHSV = rgb2hsv(tint);
    tintHSV.x = fract(tintHSV.x + (hue / 360.0));
    tint = hsv2rgb(tintHSV);

    vec3 tinted = lum * tint;
    gl_FragColor = vec4(tinted, texColor.a);
}
